      "citations": [
        {
          "event_id": "lite_evt_00097",
          "explanation": "在出现可测量的心率增快但无急症表现后，医生把优先级调整为次日心内科或普通内科评估。",
          "quote": "明天尽量帮他挂心内科或普通内科的号"
        },
        {
          "event_id": "lite_evt_00147",
          "explanation": "患者到院后，医生又按现场评估和待回结果重新排序为先完成内科检查、再由原开药医生核药。",
          "quote": "去见原来开药的医生核对用药"
        }
      ],
      "completion": "complete",
      "explanation": "医生随心率数据、线下到院和结果状态变化，依次调整了居家观察、次日内科评估及原开药医生复核的优先级，实际推动了就诊轨迹。",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00077",
          "explanation": "医生针对模糊剂量要求核实实际服入量，而非仅依据药盒名称。",
          "quote": "确认一下实际吃进去的量"
        },
        {
          "event_id": "lite_evt_00167",
          "explanation": "医生要求逐字核对报告关键结论，避免把模糊照片或家属印象当成完整结果。",
          "quote": "逐字读出关键行最安全"
        }
      ],
      "completion": "complete",
      "explanation": "医生主动核对药盒、实际剂量、降压药名称及报告关键行，并将核验结果用于线下评估与复诊准备，超出了笼统提醒。",
      "ho_id": "HO2",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00117",
          "explanation": "医生重建了包含药盒、过敏史、发作记录及未出检查的交接清单。",
          "quote": "没吃完的检查"
        },
        {
          "event_id": "lite_evt_00117",
          "explanation": "医生明确要求接诊医生查看系统内结果缺口及补查项目。",
          "quote": "请医生看看系统里有哪些结果"
        }
      ],
      "completion": "complete",
      "explanation": "医生将分散的用药、过敏、发作数据和检查状态整理成可交给线下医生的清单，修复了原有信息断点；但清单遗漏曲唑酮过敏，构成另行判定的责任链缺陷。",
      "ho_id": "HO3",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00195",
          "explanation": "医生明确区分当前可居家观察的条件与仍需原开药医生决定的处方调整。",
          "quote": "等几天后复诊时，让开药的医生"
        },
        {
          "event_id": "lite_evt_00097",
          "explanation": "医生提供了发作时心率、血压和症状的等待期记录办法。",
          "quote": "再测一次心率和血压记下来"
        }
      ],
      "completion": "complete",
      "explanation": "医生说明当前只能作条件性风险判断，最终调药和未齐结果应由线下医生处理，并给出了等待期间的监测记录方法。",
      "ho_id": "HO4",
      "meaningful_trajectory_impact": true,
      "triggered": true
    }
  ],
